/* Night Map service worker — generated by scripts/build-sw.mjs at build time. */
// Three caches, deliberately:
//   shell  — versioned per build, so a new deployment replaces the app shell.
//   data   — 311 snapshots and the building registry, refreshed from the network.
//   tiles  — terrain and building tiles; large, stable, never cleared nightly.
const SHELL_CACHE = 'night-map-shell-__BUILD_ID__';
const DATA_CACHE = 'night-map-data-v1';
const TILE_CACHE = 'night-map-tiles-v1';
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting())
      .catch((err) => console.warn('[night-map-sw] precache incomplete', err)),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith('night-map-shell-') && key !== SHELL_CACHE)
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

const offline = () => new Response('Night Map is offline and has no cached copy.', { status: 503 });

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  const path = url.pathname;

  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);
          const cache = await caches.open(SHELL_CACHE);
          cache.put('/index.html', response.clone());
          return response;
        } catch {
          return (await caches.match('/index.html')) || (await caches.match('/')) || offline();
        }
      })(),
    );
    return;
  }

  // The registry and the map's abandoned-building extract change when the
  // nightly job publishes. Serve the cached copy immediately, refresh it in the
  // background, and use the new one next time.
  if (path === '/buildings/registry.json' || path === '/buildings/abandoned.json') {
    event.respondWith(
      (async () => {
        const cache = await caches.open(DATA_CACHE);
        const network = fetch(request)
          .then((response) => {
            if (response.ok) cache.put(request, response.clone());
            return response;
          })
          .catch(() => null);
        const cached = await cache.match(request);
        if (cached) {
          event.waitUntil(network);
          return cached;
        }
        return (await network) || offline();
      })(),
    );
    return;
  }

  // Incident snapshots are small and dated; prefer the network so a nightly
  // refresh is visible, but keep the last copy for offline use.
  if (path.startsWith('/incidents/')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(DATA_CACHE);
        try {
          const response = await fetch(request);
          if (response.ok) cache.put(request, response.clone());
          return response;
        } catch {
          return (await cache.match(request)) || offline();
        }
      })(),
    );
    return;
  }

  // Terrain and building tiles are stable and expensive to re-fetch.
  if (path.startsWith('/terrain/') || path.startsWith('/buildings/')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(TILE_CACHE);
        const cached = await cache.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) cache.put(request, response.clone());
        return response;
      })(),
    );
    return;
  }

  event.respondWith(
    (async () => {
      const cached = await caches.match(request);
      if (cached) return cached;
      const response = await fetch(request);
      if (response.ok) {
        const cache = await caches.open(SHELL_CACHE);
        cache.put(request, response.clone());
      }
      return response;
    })(),
  );
});
